    def bkt(X, Y):
        return bracket(bd, X, Y)

    def apply_bracket(X, res_dict):
        """Compute [X, sum_Z c_Z * Z} = sum_Z c_Z * [X, Z}."""
        out = {}
        for Z, c in res_dict.items():
            bXZ = bkt(X, Z)
            for W, d in bXZ.items():
