import json
from fractions import Fraction

def check_gamma_antisymmetry(n):
    with open(f'data/C_{n}_gamma.json') as f:
        d = json.load(f)
    with open(f'data/C_{n}_structure.json') as f:
        sd = json.load(f)

    parity = sd['parity']
    gamma_list = d['inhomogeneous_deformation']['gamma_coefficients']

    # Build gamma dict: (X,Y,Z) -> {gb: Fraction}
    gamma = {}
    for e in gamma_list:
        key = (e['X'], e['Y'], e['Z'])
        gamma[key] = {lbl: Fraction(v) for lbl,v in e['gamma_coeff'].items()}

    # Check gamma(X,Y,Z) = -(-1)^{pX*pY} * gamma(Y,X,Z) for all entries
    errors = []
    for (X,Y,Z), gb_d in gamma.items():
        sign = (-1)**(parity[X]*parity[Y])
        yx_key = (Y,X,Z)
        yx = gamma.get(yx_key, {})
        # gamma(X,Y,Z) should equal -sign * gamma(Y,X,Z)
        for lbl, c in gb_d.items():
            expected = -Fraction(sign) * yx.get(lbl, Fraction(0))
            if c != expected:
                errors.append(f'n={n}: gamma({X},{Y})[{Z}][{lbl}]={c} but -(-1)^{{...}}*gamma({Y},{X})={expected}')

    # Also check that all (Y,X,Z) entries are accounted for
    for (Y,X,Z), gb_d in gamma.items():
        sign = (-1)**(parity[Y]*parity[X])
        xy_key = (X,Y,Z)
        xy = gamma.get(xy_key, {})
        for lbl, c in gb_d.items():
            expected = -Fraction(sign) * xy.get(lbl, Fraction(0))
            if c != expected:
                errors.append(f'n={n}: gamma({Y},{X})[{Z}][{lbl}]={c} but -(-1)^{{...}}*gamma({X},{Y})={expected}')

    return errors

for n in [1,2,3]:
    errs = check_gamma_antisymmetry(n)
    if errs:
        print(f'n={n}: {len(errs)} errors')
        for e in errs[:3]:
            print(' ', e)
    else:
        print(f'n={n}: gamma antisymmetry OK')
