    for entry in gamma_list:
        X, Y, Z = entry["X"], entry["Y"], entry["Z"]
        gb_coeff_dict = {lbl: Fraction(c) for lbl, c in entry["gamma_coeff"].items()}

        # Evaluate: coeff = sum_gb gb_value * gb_coeff
