        if all_basis_parities[Z] != expected_pZ:
            errors.append(
                f"Parity error (delta f)({X},{Y})[{Z}]: "
                f"expected parity {expected_pZ}, got {all_basis_parities[Z]}"
            )
    return errors


def main():
